def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def as_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return int(v[0]), int(v[1])
        return None

    def get_first_pos(obs, keys, default=(0, 0)):
        for k in keys:
            p = as_pos(obs.get(k))
            if p is not None:
                return p
        return default

    def move_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def move_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def grid_dims(obs):
        w = obs.get("grid_width", 0) or 0
        h = obs.get("grid_height", 0) or 0
        try:
            w = int(w)
        except Exception:
            w = 0
        try:
            h = int(h)
        except Exception:
            h = 0
        return max(0, w), max(0, h)

    def iter_positions(value):
        if isinstance(value, dict):
            for v in value.values():
                p = as_pos(v)
                if p is not None:
                    yield p
                elif isinstance(v, (list, tuple)):
                    for item in v:
                        p = as_pos(item)
                        if p is not None:
                            yield p
        elif isinstance(value, (list, tuple)):
            for item in value:
                p = as_pos(item)
                if p is not None:
                    yield p
                elif isinstance(item, dict):
                    for kk in ("position", "pos", "location", "loc", "x_y"):
                        p2 = as_pos(item.get(kk))
                        if p2 is not None:
                            yield p2
                            break

    def best_nearest(src, items):
        best = None
        best_d = None
        for p in items:
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def best_farthest(src, items):
        best = None
        best_d = None
        for p in items:
            d = manhattan(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_first_pos(observation, ("self_position", "agent_position", "position", "self_pos"), (0, 0))
    ox, oy = get_first_pos(observation, ("opponent_position", "enemy_position", "adversary_position"), (sx, sy))
    w, h = grid_dims(observation)

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            return move_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_farthest((ox, oy), corners) or (0, 0)
        return move_toward((sx, sy), target)

    if env == "territory_control":
        targets = []
        for k in ("unclaimed_cells", "opponent_territory", "territory_targets", "frontier_cells", "neutral_cells"):
            v = observation.get(k)
            if v:
                targets.extend(list(iter_positions(v)))
        if targets:
            return move_toward((sx, sy), best_nearest((sx, sy), targets))
        # If no explicit territory targets, pressure opponent or drift center.
        if (ox, oy) != (sx, sy):
            return move_toward((sx, sy), (ox, oy))
        cx, cy = max(0, w // 2), max(0, h // 2)
        return move_toward((sx, sy), (cx, cy))

    # resource_collection (default)
    resources = []
    for k in ("resources", "resource_positions", "food", "collectibles", "items", "targets"):
        v = observation.get(k)
        if v:
            resources.extend(list(iter_positions(v)))

    if resources:
        # Prefer resource that is not obviously contested by the opponent.
        best = None
        best_score = None
        for r in resources:
            sdist = manhattan((sx, sy), r)
            odist = manhattan((ox, oy), r)
            score = sdist * 2 - odist  # lower is better; closer for self, farther from opponent
            if best is None or score < best_score:
                best = r
                best_score = score
        return move_toward((sx, sy), best)

    # If no resources visible, avoid collision pressure when close.
    if manhattan((sx, sy), (ox, oy)) <= 2:
        away = move_away((sx, sy), (ox, oy))
        if away != [0, 0]:
            return away

    # Mild center-seeking fallback for exploration.
    if w > 0 and h > 0:
        return move_toward((sx, sy), (w // 2, h // 2))

    return [0, 0]

